def sync_from_supabase():
    if time.time() - cache.get("last_sync", 0) < 20:
        return
    try:
        url = f"{SUPABASE_URL}/rest/v1/app_settings?select=key,value"
        r = requests.get(url, headers=supa_headers(), timeout=3)
        if r.status_code == 200:
            for row in r.json():
                k, v = row.get("key"), row.get("value")
                if not k or not v:
                    continue
                try:
                    parsed = json.loads(v)
                except:
                    parsed = v
                if k == "meta_ai_kb":
                    cache["kb"] = parsed
                elif k == "meta_ai_rules":
                    cache["rules"] = parsed
                elif k == "meta_ai_system_prompt":
                    cache["prompt"] = DEFAULT_SYSTEM_PROMPT
                elif k == "meta_ai_accounts":
                    cache["accounts"] = parsed
                    if isinstance(parsed, list):
                        ACCOUNTS_STORE[:] = parsed
                elif k == "meta_ai_clients":
                    cache["clients"] = parsed
                    if isinstance(parsed, list):
                        AGENCY_CLIENTS_STORE[:] = parsed
                elif k == "meta_ai_bot_enabled":
                    cache["bot_enabled"] = bool(parsed)
                elif k == "meta_ai_approval_mode":
                    cache["approval_mode"] = str(parsed) if parsed else "auto"
                elif k == "meta_ai_scheduled_posts":
                    cache["scheduled_posts"] = parsed if isinstance(parsed, list) else []
            cache["last_sync"] = time.time()
    except Exception as e:
        print(f"[Supabase Sync] Using defaults: {e}")

def push_setting(key, value):
    try:
        url = f"{SUPABASE_URL}/rest/v1/app_settings"
        val_str = json.dumps(value, ensure_ascii=False) if isinstance(value, (dict, list)) else str(value)
        requests.post(url, headers=supa_headers(), json={"key": key, "value": val_str}, timeout=3)
    except Exception as e:
        print(f"[Supabase Push] {key}: {e}")

sync_from_supabase()

AGENCY_CLIENTS_STORE = cache.get("clients") or []

def get_kb_data():
    raw = cache.get("kb", DEFAULT_KB)
    if not isinstance(raw, list):
        return []
    seen = set()
    unique_kb = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        key = (item.get("question", "") + "||" + item.get("answer", "")).strip().lower()
        if key not in seen:
            seen.add(key)
            unique_kb.append(item)
    return unique_kb

def get_rules_data():
    return cache.get("rules", DEFAULT_RULES)

def get_system_prompt(client_id=None):
    cid = client_id or current_client_id()
    base_prompt = cache.get("prompt", DEFAULT_SYSTEM_PROMPT)
    client = next((c for c in AGENCY_CLIENTS_STORE if c.get("id") == cid), None)
    if client and client.get("name"):
        return f"{base_prompt}\n\nملاحظة: أنت تعمل كمنسق وراد آلي مخصص للعميل: {client.get('name')}."
    return base_prompt

def search_kb(query, client_id=None):
    cid = client_id or current_client_id()
    items = get_kb_data()
    if not items or not query or not str(query).strip():
        return ""
    client_items = [i for i in items if (i.get("client_id") or "client_default") == cid]
    words = [w for w in re.split(r'\s+', str(query).lower()) if len(w) >= 2]
    scored = []
    for item in client_items:
        text = (item.get("question", "") + " " + item.get("answer", "")).lower()
        score = sum(1 for w in words if w in text)
        if score > 0:
            scored.append((score, item))
    scored.sort(key=lambda x: x[0], reverse=True)
    if not scored:
        return ""
    res_lines = []
    for _, i in scored[:2]:
        res_lines.append("- " + str(i.get('question')) + ": " + str(i.get('answer')))
    return "\n".join(res_lines)

def check_custom_rules(message, client_id=None, post_url_or_id=None):
    cid = client_id or current_client_id()
    rules = get_rules_data()
    if not rules or not message or not isinstance(message, str):
        return None
    msg_lower = message.lower().strip()
    target_post = str(post_url_or_id or "").strip().lower()
    
    for rule in rules:
        if not rule.get("is_active", True):
            continue
        r_cid = rule.get("client_id") or "client_default"
        if r_cid != cid:
            continue
        
        # Check Post-Specific Rule Filter (if rule is tied to a specific post URL or ID)
        rule_post = str(rule.get("post_url") or rule.get("post_id") or "").strip().lower()
        if rule_post:
            if not target_post:
                continue
            if rule_post not in target_post and target_post not in rule_post:
                continue

        trigger = (rule.get("trigger") or "").lower().strip()
        if not trigger or trigger == "*":
            if rule_post and (rule_post in target_post or target_post in rule_post):
                return rule
            continue

        match_type = rule.get("match_type", "contains")
        if match_type == "exact" and msg_lower == trigger:
            return rule
        elif match_type == "contains" and trigger in msg_lower:
            return rule
        elif match_type == "startswith" and msg_lower.startswith(trigger):
            return rule
    return None

def generate_reply(user_message, platform="facebook"):
    if not user_message or not str(user_message).strip():
        return "أهلاً بك! تم استلام رسالتك وسيتم التواصل معك فوراً."
    
    # 1. Custom Rules exact/contains check
    rule = check_custom_rules(user_message)
    if rule:
        return rule.get("response") or "أهلاً بك! تم الرد على استفسارك."
        
    # 2. Knowledge Base RAG Search
    rag_context = search_kb(user_message)
    
    # If no relevant RAG context found and no custom rule, use safe polite fallback instead of hallucinating
    if not rag_context or len(rag_context.strip()) < 5:
        return "أهلاً بك! تم تحويل استفسارك لمسؤول الحسابات وسيتم الرد عليك بالتفاصيل في أقرب وقت. "
        
    # 3. Controlled LLM Response with RAG Context
    cid = current_client_id()
    if GROQ_API_KEY:
        reply = _call_groq(user_message, rag_context, platform, cid)
        if reply:
            return reply
    if OPENROUTER_API_KEY:
        reply = _call_openrouter(user_message, rag_context, platform, cid)
        if reply:
            return reply
            
    lines = rag_context.strip().split("\n")
    first = lines[0]
    if ": " in first:
        return f"أهلاً بيك! {first.split(': ', 1)[1]}"
    return f"أهلاً بيك! {rag_context}" 

def _call_groq(user_message, rag_context, platform, client_id=None):
    system_prompt = get_system_prompt(client_id)
    if rag_context:
        system_prompt += f"\n\nمعلومات الشركة:\n{rag_context}\n\nاستخدم هذه المعلومات للرد بدقة."
    try:
        res = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {GROQ_API_KEY}", "Content-Type": "application/json"},
            json={"model": "llama-3.3-70b-versatile", "messages": [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_message}], "max_tokens": 300, "temperature": 0.3, "top_p": 0.85, "presence_penalty": 0.2},
            timeout=15
        )
        if res.status_code == 200:
            return res.json()["choices"][0]["message"]["content"].strip()
    except Exception as e:
        print(f"[Groq Error] {e}")
    return None

def _call_openrouter(user_message, rag_context, platform, client_id=None):
    system_prompt = get_system_prompt(client_id)
    if rag_context:
        system_prompt += f"\n\nمعلومات الشركة:\n{rag_context}\n\nاستخدم هذه المعلومات للرد بدقة."
    try:
        res = requests.post(
            "https://openrouter.ai/api/v1/chat/completions",
            headers={"Authorization": f"Bearer {OPENROUTER_API_KEY}", "Content-Type": "application/json"},
            json={"model": "meta-llama/llama-3.3-70b-instruct", "messages": [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_message}], "max_tokens": 300, "temperature": 0.3, "top_p": 0.85, "presence_penalty": 0.2},
            timeout=15
        )
        if res.status_code == 200:
            return res.json()["choices"][0]["message"]["content"].strip()
    except Exception as e:
        print(f"[OpenRouter Error] {e}")
    return None

