@app.route('/static/<path:filename>')
def serve_static(filename):
    root_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    static_dir = os.path.join(root_dir, 'static')
    return send_from_directory(static_dir, filename)

def log_event(event_type, sender, message, reply, private_reply=None, client_id=None):
    cid = client_id or current_client_id()
    entry = {"id": int(time.time()*1000), "client_id": cid, "type": event_type, "sender": sender, "sender_name": sender,
             "message": message, "reply": reply, "private_reply": private_reply, "time": datetime.now().strftime("%H:%M:%S"),
             "timestamp": time.time()}
    activity_log.append(entry)
    if len(activity_log) > 100:
        activity_log.pop(0)
    push_setting("meta_ai_activity", activity_log)

from flask import has_request_context

def current_client_id():
    """Safely retrieve the active client ID.
    Returns a default client ID when called outside an HTTP request context.
    """
    if not has_request_context():
        # No request context; fallback to default client identifier
        return "client_default"
    cid = session.get("active_client_id")
    if cid and any(c.get("id") == cid and c.get("is_active", True) for c in AGENCY_CLIENTS_STORE):
        return cid
    nxt = next((c.get("id") for c in AGENCY_CLIENTS_STORE if c.get("is_active", True)), "client_default")
    session["active_client_id"] = nxt
    session.modified = True
    return nxt

