RCON = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36]

def _sub_word(w): return [SBOX[b] for b in w]
def _rot_word(w): return w[1:] + w[:1]

def _key_expansion(key_bytes):
    w = []
    for i in range(8): w.append(list(key_bytes[4*i:4*i+4]))
    for i in range(8, 60):
        temp = list(w[i-1])
        if i % 8 == 0:
            temp = [b ^ r for b, r in zip(_sub_word(_rot_word(temp)), [RCON[i//8 - 1], 0, 0, 0])]
        elif i % 8 == 4:
            temp = _sub_word(temp)
        w.append([b1 ^ b2 for b1, b2 in zip(w[i-8], temp)])
    round_keys = []
    for r in range(15):
        rk = []
        for i in range(4): rk.extend(w[r*4 + i])
        round_keys.append(bytes(rk))
    return round_keys

def _mul(a, b):
    p = 0
    for _ in range(8):
        if b & 1: p ^= a
        hi = a & 0x80
        a = (a << 1) & 0xff
        if hi: a ^= 0x1b
        b >>= 1
    return p

def _aes_encrypt_block(block, round_keys):
    state = list(block)
    for i in range(16): state[i] ^= round_keys[0][i]
    for r in range(1, 14):
        state = [SBOX[b] for b in state]
        state = [
            state[0], state[5], state[10], state[15],
            state[4], state[9], state[14], state[3],
            state[8], state[13], state[2], state[7],
            state[12], state[1], state[6], state[11]
        ]
        new_s = [0]*16
        for c in range(4):
            col = state[c*4:(c+1)*4]
            new_s[c*4 + 0] = _mul(2, col[0]) ^ _mul(3, col[1]) ^ col[2] ^ col[3]
            new_s[c*4 + 1] = col[0] ^ _mul(2, col[1]) ^ _mul(3, col[2]) ^ col[3]
            new_s[c*4 + 2] = col[0] ^ col[1] ^ _mul(2, col[2]) ^ _mul(3, col[3])
            new_s[c*4 + 3] = _mul(3, col[0]) ^ col[1] ^ col[2] ^ _mul(2, col[3])
        state = new_s
        for i in range(16): state[i] ^= round_keys[r][i]
    state = [SBOX[b] for b in state]
    state = [
        state[0], state[5], state[10], state[15],
        state[4], state[9], state[14], state[3],
        state[8], state[13], state[2], state[7],
        state[12], state[1], state[6], state[11]
    ]
    for i in range(16): state[i] ^= round_keys[14][i]
    return bytes(state)

def ghash_mul(x, y):
    R = 0xe1000000000000000000000000000000
    x_int = int.from_bytes(x, 'big')
    y_int = int.from_bytes(y, 'big')
    z = 0
    v = x_int
    for i in range(128):
        if (y_int >> (127 - i)) & 1:
            z ^= v
        if v & 1:
            v = (v >> 1) ^ R
        else:
            v >>= 1
    return z.to_bytes(16, 'big')

def ghash(h, aad, ciphertext):
    aad_padded = aad + b'\x00' * ((16 - (len(aad) % 16)) % 16)
    ct_padded = ciphertext + b'\x00' * ((16 - (len(ciphertext) % 16)) % 16)
    len_block = (len(aad) * 8).to_bytes(8, 'big') + (len(ciphertext) * 8).to_bytes(8, 'big')
    data = aad_padded + ct_padded + len_block
    y = b'\x00' * 16
    for i in range(0, len(data), 16):
        block = bytes(a ^ b for a, b in zip(y, data[i:i+16]))
        y = ghash_mul(block, h)
    return y

def aes_gcm_encrypt(key_bytes, iv_bytes, plaintext_bytes, aad_bytes=b''):
    round_keys = _key_expansion(key_bytes)
    h = _aes_encrypt_block(b'\x00'*16, round_keys)
    j0 = iv_bytes + b'\x00\x00\x00\x01'
    
    ciphertext = bytearray()
    counter_int = int.from_bytes(j0, 'big')
    for i in range(0, len(plaintext_bytes), 16):
        counter_int = (counter_int & ~0xffffffff) | ((counter_int + 1) & 0xffffffff)
        cb = counter_int.to_bytes(16, 'big')
        ks = _aes_encrypt_block(cb, round_keys)
        chunk = plaintext_bytes[i:i+16]
        for p, k in zip(chunk, ks):
            ciphertext.append(p ^ k)
    ct = bytes(ciphertext)
    g = ghash(h, aad_bytes, ct)
    e_j0 = _aes_encrypt_block(j0, round_keys)
    tag = bytes(a ^ b for a, b in zip(g, e_j0))
    return ct, tag

def aes_gcm_decrypt(key_bytes, iv_bytes, ciphertext_bytes, tag_bytes, aad_bytes=b''):
    round_keys = _key_expansion(key_bytes)
    h = _aes_encrypt_block(b'\x00'*16, round_keys)
    j0 = iv_bytes + b'\x00\x00\x00\x01'
    
    g = ghash(h, aad_bytes, ciphertext_bytes)
    e_j0 = _aes_encrypt_block(j0, round_keys)
    expected_tag = bytes(a ^ b for a, b in zip(g, e_j0))
    if not secrets.compare_digest(expected_tag, tag_bytes):
        raise ValueError('Authentication tag mismatch')
        
    plaintext = bytearray()
    counter_int = int.from_bytes(j0, 'big')
    for i in range(0, len(ciphertext_bytes), 16):
        counter_int = (counter_int & ~0xffffffff) | ((counter_int + 1) & 0xffffffff)
        cb = counter_int.to_bytes(16, 'big')
        ks = _aes_encrypt_block(cb, round_keys)
        chunk = ciphertext_bytes[i:i+16]
        for c, k in zip(chunk, ks):
            plaintext.append(c ^ k)
    return bytes(plaintext)

def encrypt_token(token, secret=None):
    if not token:
        return token
    sec = secret or os.environ.get('APP_SECRET') or os.environ.get('SECRET_KEY') or 'meta_ai_moderator_free_tier_secret_key_2026'
    key_bytes = hashlib.sha256(sec.encode('utf-8')).digest()
    iv = secrets.token_bytes(12)
    ct, tag = aes_gcm_encrypt(key_bytes, iv, str(token).encode('utf-8'))
    payload = iv + tag + ct
    return 'gcm:' + base64.b64encode(payload).decode('utf-8')

def decrypt_token(encrypted_token, secret=None):
    if not encrypted_token or not isinstance(encrypted_token, str):
        return encrypted_token
    sec = secret or os.environ.get('APP_SECRET') or os.environ.get('SECRET_KEY') or 'meta_ai_moderator_free_tier_secret_key_2026'
    key_bytes = hashlib.sha256(sec.encode('utf-8')).digest()
    if encrypted_token.startswith('gcm:'):
        try:
            raw = base64.b64decode(encrypted_token[4:])
            iv, tag, ct = raw[:12], raw[12:28], raw[28:]
            pt = aes_gcm_decrypt(key_bytes, iv, ct, tag)
            return pt.decode('utf-8')
        except Exception:
            return None
    else:
        try:
            return base64.b64decode(encrypted_token.encode('utf-8')).decode('utf-8')
        except Exception:
            return None

def encrypt(text):
    return encrypt_token(text)

def decrypt(text):
    return decrypt_token(text)

def generate_pkce_pair(length=64):
    if length < 43 or length > 128:
        length = 64
    code_verifier = secrets.token_urlsafe(96)[:length]
    digest = hashlib.sha256(code_verifier.encode('ascii')).digest()
    code_challenge = base64.urlsafe_b64encode(digest).decode('ascii').rstrip('=')
    state = secrets.token_urlsafe(32)
    return {
        'code_verifier': code_verifier,
        'code_challenge': code_challenge,
        'code_challenge_method': 'S256',
        'state': state
    }

