@app.route('/api/oauth/attach_page', methods=['POST'])
def api_attach_page():
    data = request.get_json() or {}
    page_id = str(data.get('page_id', ''))
    client_id = data.get('client_id') or session.get('oauth_client_id') or request.cookies.get('oauth_client_id') or current_client_id()
    tok = session.get('pending_token')
    pages = discover_pages(tok) if tok else []
    page = next((p for p in pages if str(p['id']) == page_id), None)
    
    if not page and pages:
        page = pages[0]
        page_id = str(page['id'])

    if not page:
        return jsonify({'error': 'الصفحة غير موجودة'}), 404

    tok = page.get('access_token') or PAGE_ACCESS_TOKEN
    expires = (datetime.now(timezone.utc) + timedelta(days=60)).isoformat()

    existing_fb = next((a for a in ACCOUNTS_STORE if str(a['id']) == str(page['id'])), None)
    fb_account = {
        'client_id': client_id,
        'platform': 'facebook',
        'id': str(page['id']),
        'name': page.get('name'),
        'avatar_url': (page.get('picture') or {}).get('data', {}).get('url'),
        'access_token': tok,
        'access_token_enc': encrypt(tok),
        'token_expires_at': expires,
        'status': 'connected',
    }
    if existing_fb:
        existing_fb.update(fb_account)
    else:
        ACCOUNTS_STORE.append(fb_account)

    client_obj = next((c for c in AGENCY_CLIENTS_STORE if c.get('id') == client_id), None)
    if client_obj:
        client_obj['page_id'] = str(page['id'])
        client_obj['fb_connected'] = True

    ig = page.get('instagram_business_account')
    if ig:
        existing_ig = next((a for a in ACCOUNTS_STORE if str(a['id']) == str(ig['id'])), None)
        ig_account = {
            'client_id': client_id,
            'platform': 'instagram',
            'id': str(ig['id']),
            'name': ig.get('username'),
            'avatar_url': ig.get('profile_picture_url'),
            'access_token': tok,
            'access_token_enc': encrypt(tok),
            'token_expires_at': expires,
            'status': 'connected',
            'parent_page_id': str(page['id']),
        }
        if existing_ig:
            existing_ig.update(ig_account)
        else:
            ACCOUNTS_STORE.append(ig_account)

        if client_obj:
            client_obj['ig_id'] = str(ig['id'])
            client_obj['ig_connected'] = True

    try:
        requests.post(f"{GRAPH_URL}/{page['id']}/subscribed_apps", params={
            'subscribed_fields': 'messages,messaging_postbacks,feed',
            'access_token': tok,
        }, timeout=20)
    except Exception as e:
        print('[subscribe warning]', e)

    session.pop('pending_token', None)
    session.pop('oauth_client_id', None)
    session.modified = True
    
    push_setting("meta_ai_accounts", ACCOUNTS_STORE)
    push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
    
    return jsonify({
        'ok': True,
        'facebook': page.get('name'),
        'instagram': ig.get('username') if ig else None
    })

