PUBLIC_PATHS = {
    '/api/login', '/api/logout', '/api/me',
    '/webhook', '/api/oauth_url',
    '/api/oauth/callback', '/oauth_callback',
    '/api/auth/facebook',
    '/api/cron/refresh_tokens',
    '/api/oauth/pending_pages',
    '/api/oauth/attach_page',
    '/api/oauth/start',
    '/api/data-deletion',
    '/api/health',
}

@app.before_request
def global_api_guard():
    p = request.path
    if not p.startswith('/api/'):
        return
    if p in PUBLIC_PATHS:
        return
    if request.method == 'OPTIONS':
        return
    
    # Check Bearer or API Key auth header for secure endpoints or API access
    auth_header = request.headers.get("Authorization", "")
    api_key_header = request.headers.get("X-API-Key", "")
    expected_secret = os.environ.get("ADMIN_API_KEY") or os.environ.get("APP_SECRET") or os.environ.get("SECRET_KEY")
    if expected_secret:
        if auth_header.startswith("Bearer "):
            token = auth_header[7:].strip()
            if hmac.compare_digest(token, expected_secret):
                return
        if api_key_header and hmac.compare_digest(api_key_header, expected_secret):
            return

    if 'uid' not in session:
        return jsonify({"error": "Unauthorized"}), 401

