@app.route("/api/meta/diagnose", methods=["GET"])
def api_meta_diagnose():
    """تشخيص التوكن: بيقول التوكن شايف إيه (صفحات/IG/صلاحيات) بدون كشف السر."""
    tok = PAGE_ACCESS_TOKEN
    out = {"has_token": bool(tok), "token_len": len(tok) if tok else 0, "pages": [], "errors": []}
    if not tok:
        out["errors"].append("PAGE_ACCESS_TOKEN غير متظبط في الـ env")
        return jsonify(out), 200
    try:
        me = requests.get(f"{GRAPH_URL}/me?fields=id,name", params={"access_token": tok}, timeout=10)
        out["me"] = me.json() if me.status_code == 200 else {"status": me.status_code, "error": me.text[:200]}
    except Exception as e:
        out["errors"].append(f"me: {e}")
    try:
        perms = requests.get(f"{GRAPH_URL}/me/permissions", params={"access_token": tok}, timeout=10)
        if perms.status_code == 200:
            out["granted_permissions"] = [p["permission"] for p in perms.json().get("data", []) if p.get("status") == "granted"]
    except Exception as e:
        out["errors"].append(f"permissions: {e}")
    try:
        acc = requests.get(
            f"{GRAPH_URL}/me/accounts?fields=id,name,access_token,instagram_business_account{{id,username}}&limit=25",
            params={"access_token": tok}, timeout=12)
        if acc.status_code == 200:
            for pg in acc.json().get("data", []):
                out["pages"].append({
                    "id": pg.get("id"),
                    "name": pg.get("name"),
                    "has_page_token": bool(pg.get("access_token")),
                    "instagram": pg.get("instagram_business_account", {}).get("username") or None,
                    "ig_id": pg.get("instagram_business_account", {}).get("id") or None
                })
        else:
            out["errors"].append(f"/me/accounts → {acc.status_code}: {acc.text[:200]}")
    except Exception as e:
        out["errors"].append(f"accounts: {e}")
    out["page_count"] = len(out["pages"])

    # Probe each data source with the resolved page token
    if out["pages"]:
        pg = out["pages"][0]
        pid = pg["id"]; igid = pg.get("ig_id")
        # get the page token
        ptok = tok
        try:
            pt = requests.get(f"{GRAPH_URL}/{pid}?fields=access_token", params={"access_token": tok}, timeout=10)
            if pt.status_code == 200 and pt.json().get("access_token"):
                ptok = pt.json()["access_token"]
        except Exception:
            pass
        probe = {}
        def _count(label, url):
            try:
                r = requests.get(url, timeout=12)
                if r.status_code == 200:
                    probe[label] = len(r.json().get("data", []))
                else:
                    probe[label] = f"ERR {r.status_code}: {r.text[:150]}"
            except Exception as e:
                probe[label] = f"EXC {e}"
        _count("fb_messenger", f"{GRAPH_URL}/{pid}/conversations?platform=messenger&fields=id,snippet&limit=25&access_token={ptok}")
        # IG DM — try both page-scoped and IG-user-scoped endpoints
        try:
            r = requests.get(f"{GRAPH_URL}/{pid}/conversations?platform=instagram&fields=id&limit=10&access_token={ptok}", timeout=10)
            probe["ig_dm_via_page"] = len(r.json().get("data", [])) if r.status_code == 200 else f"ERR {r.status_code}: {r.text[:180]}"
        except Exception as e:
            probe["ig_dm_via_page"] = f"TIMEOUT {e}"
        if igid:
            try:
                r = requests.get(f"{GRAPH_URL}/{igid}/conversations?fields=id&limit=10&access_token={ptok}", timeout=10)
                probe["ig_dm_via_iguser"] = len(r.json().get("data", [])) if r.status_code == 200 else f"ERR {r.status_code}: {r.text[:180]}"
            except Exception as e:
                probe["ig_dm_via_iguser"] = f"TIMEOUT {e}"
        # Count ACTUAL comments on FB posts
        try:
            r = requests.get(f"{GRAPH_URL}/{pid}/feed?fields=id,comments.limit(50){{id,message}}&limit=25&access_token={ptok}", timeout=20)
            if r.status_code == 200:
                posts = r.json().get("data", [])
                probe["fb_posts"] = len(posts)
                probe["fb_comments_total"] = sum(len(p.get("comments", {}).get("data", [])) for p in posts)
            else:
                probe["fb_posts"] = f"ERR {r.status_code}: {r.text[:150]}"
        except Exception as e:
            probe["fb_posts"] = f"EXC {e}"
        if igid:
            try:
                r = requests.get(f"{GRAPH_URL}/{igid}/media?fields=id,comments_count,comments.limit(50){{id,text}}&limit=25&access_token={ptok}", timeout=20)
                if r.status_code == 200:
                    media = r.json().get("data", [])
                    probe["ig_media"] = len(media)
                    probe["ig_comments_total"] = sum(m.get("comments_count", 0) for m in media)
                else:
                    probe["ig_media"] = f"ERR {r.status_code}: {r.text[:150]}"
            except Exception as e:
                probe["ig_media"] = f"EXC {e}"
        out["probe"] = probe

    out["verdict"] = ("جاهز — الصفحات ظاهرة، السحب المفروض يشتغل" if out["pages"]
                      else "التوكن شغّال بس مفيش صفحات ظاهرة — راجع صلاحيات/تعيين الصفحة للـ System User")
    return jsonify(out), 200

