# 
# 100% FREE ZERO-COST OPEN SOURCE ARCHITECTURE ($0/mo Forever)
# 

class FreeLRUCache:
    def __init__(self, max_size=1000):
        self.cache = {}
        self.max_size = max_size

    def get(self, key):
        item = self.cache.get(key)
        if not item:
            return None
        val, expiry = item
        if time.time() > expiry:
            del self.cache[key]
            return None
        return val

    def set(self, key, value, ttl_seconds=300):
        if len(self.cache) >= self.max_size:
            first_key = next(iter(self.cache))
            del self.cache[first_key]
        self.cache[key] = (value, time.time() + ttl_seconds)

free_lru_cache = FreeLRUCache()

def with_free_cache(key, ttl_seconds, fetch_fn):
    cached = free_lru_cache.get(key)
    if cached is not None:
        return cached
    fresh = fetch_fn()
    if fresh is not None:
        free_lru_cache.set(key, fresh, ttl_seconds)
    return fresh

